import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listUserPostsHandler } from "../handlers/listUserPostsHandler";
import type { ApiError } from "../runtime/client";

type Data = Awaited<ReturnType<typeof listUserPostsHandler>>;

export function useListUserPosts(
  username: string,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listUserPosts", username, bookmark],
    queryFn: () => listUserPostsHandler(username, bookmark),
    ...options,
  });
}
